import dotenv from "dotenv";
import path from "path";

dotenv.config();

/**
 * Application configuration loaded and validated from environment variables.
 *
 * Fails fast at startup when a required variable is missing so a misconfigured
 * environment surfaces immediately rather than mid-request.
 */
export interface AppConfig {
  /** Port the HTTP server listens on. */
  port: number;
  /** Comma-separated list of allowed CORS origins. */
  corsOrigins: string[];
  /** Secret used to sign session JWTs. */
  jwtSecret: string;
  /** Absolute filesystem path of the SQLite database file. */
  databasePath: string;
  /** Current Node environment (development | production | test). */
  nodeEnv: string;
}

/**
 * Read a required environment variable.
 *
 * Args:
 *   name: The environment variable name.
 *   fallback: Optional default used when the variable is unset.
 *
 * Returns:
 *   The resolved string value.
 *
 * Raises:
 *   Error: When the variable is unset and no fallback is provided.
 */
function requireEnv(name: string, fallback?: string): string {
  const value = process.env[name] ?? fallback;
  if (value === undefined || value === "") {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

/**
 * Load and validate the application configuration.
 *
 * Returns:
 *   A validated AppConfig with defaults applied for local development.
 */
export function loadConfig(): AppConfig {
  const corsRaw = requireEnv("CORS_ORIGIN", "http://localhost:3000");
  return {
    port: parseInt(requireEnv("PORT", "8000"), 10),
    corsOrigins: corsRaw.split(",").map((origin) => origin.trim()),
    jwtSecret: requireEnv("JWT_SECRET", "dev-secret-change-in-production"),
    databasePath: path.resolve(
      requireEnv("DATABASE_PATH", "./data/bookmyshow.db")
    ),
    nodeEnv: process.env.NODE_ENV ?? "development",
  };
}

export const config = loadConfig();

import { ErrorRequestHandler } from "express";

/**
 * Centralized Express error-handling middleware.
 *
 * Formats every unhandled error into a consistent JSON error envelope.
 * Mounted as the last `app.use()` so Express routes all thrown/forwarded
 * errors here. Must keep the four-argument signature for Express to treat
 * it as an error handler.
 */
export const errorHandler: ErrorRequestHandler = (err, _req, res, _next) => {
  const status = (err as { status?: number }).status ?? 500;
  const message = err.message ?? "Internal server error";
  res.status(status).json({ success: false, error: message });
};

import express, { Express, Request, Response } from "express";
import cors from "cors";
import { config } from "./config";
import { errorHandler } from "./middleware/errorHandler";

/**
 * Build and configure the Express application.
 *
 * Mounts body parsing, CORS, the liveness probe, feature routers, and the
 * centralized error handler (last). Kept separate from the server bootstrap
 * so tests can exercise the app in-process without binding a port.
 *
 * Returns:
 *   A configured Express application.
 */
export function createApp(): Express {
  const app = express();

  app.use(express.json());
  app.use(express.urlencoded({ extended: true }));
  app.use(cors({ origin: config.corsOrigins, credentials: true }));

  // Liveness probe — the single carve-out from feature routing. No DB access.
  app.get("/api/health", (_req: Request, res: Response) => {
    res.status(200).json({ status: "ok" });
  });

  // Feature routers are mounted here by later slices.

  app.use(errorHandler);

  return app;
}

import { createApp } from "./app";
import { config } from "./config";

/**
 * Server bootstrap.
 *
 * Creates the Express app and binds it to the configured port. Kept thin so
 * the app module stays importable by tests without starting a listener.
 */
function main(): void {
  const app = createApp();
  app.listen(config.port, () => {
    // eslint-disable-next-line no-console
    console.log(`BookMyShow backend listening on port ${config.port}`);
  });
}

main();

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  async rewrites() {
    // Dev proxy: forward /api/* to the backend so the shipped client stays
    // same-origin and never hardcodes the backend host.
    const backend = process.env.BACKEND_URL || "http://localhost:8000";
    return [{ source: "/api/:path*", destination: `${backend}/api/:path*` }];
  },
};

module.exports = nextConfig;

