import { describe, it, expect } from "vitest";
import { AuthService, HARDCODED_OTP } from "../services/auth.service";

/**
 * Unit tests for AuthService — the mobile + hardcoded-OTP login logic.
 */
describe("AuthService", () => {
  const service = new AuthService();

  describe("initiateLogin", () => {
    it("accepts a valid 10-digit mobile number", () => {
      expect(service.initiateLogin("9876543210")).toBe(true);
    });

    it("rejects a mobile number that is too short", () => {
      expect(service.initiateLogin("12345")).toBe(false);
    });

    it("rejects a mobile number with non-numeric characters", () => {
      expect(service.initiateLogin("98abc43210")).toBe(false);
    });

    it("rejects an empty mobile number", () => {
      expect(service.initiateLogin("")).toBe(false);
    });
  });

  describe("verifyOtp", () => {
    it("returns a signed session token for the correct OTP", () => {
      const token = service.verifyOtp("9876543210", HARDCODED_OTP);
      expect(typeof token).toBe("string");
      expect(token.split(".")).toHaveLength(3); // JWT structure
    });

    it("throws 401 for an incorrect OTP", () => {
      try {
        service.verifyOtp("9876543210", "0000");
        expect.unreachable("should have thrown");
      } catch (err) {
        expect((err as Error & { status?: number }).status).toBe(401);
        expect((err as Error).message).toBe("Invalid OTP");
      }
    });

    it("throws 400 for an invalid mobile number even with the correct OTP", () => {
      try {
        service.verifyOtp("123", HARDCODED_OTP);
        expect.unreachable("should have thrown");
      } catch (err) {
        expect((err as Error & { status?: number }).status).toBe(400);
      }
    });
  });
});

/**
 * Typed API client for the BookMyShow Replica backend.
 *
 * The base URL defaults to same-origin (empty string) so the dev-server proxy
 * or co-hosted deployment forwards `/api` to the backend. Never hardcode a
 * host here.
 */

const BASE_URL = process.env.NEXT_PUBLIC_API_URL ?? "";

/** A movie in the catalog. */
export interface Movie {
  id: number;
  title: string;
  poster: string;
  genre: string;
  rating: string;
}

/** A theatre showing movies. */
export interface Theatre {
  id: number;
  name: string;
  location: string;
}

/** A confirmed booking returned by the backend. */
export interface BookingConfirmation {
  id: number;
  confirmationId: string;
  movie: string;
  theatre: string;
  seats: string[];
  totalPrice: number;
}

/** Payload submitted to create a booking. */
export interface BookingPayload {
  mobile: string;
  movieId: number;
  theatreId: number;
  seats: string[];
  totalPrice: number;
  paymentMethod: "card" | "upi";
}

/** Error thrown for non-2xx API responses, carrying the server message. */
export class ApiError extends Error {
  constructor(message: string, public readonly status: number) {
    super(message);
    this.name = "ApiError";
  }
}

/**
 * Perform a JSON request against the backend and unwrap the envelope.
 *
 * Args:
 *   path: The request path beginning with `/api`.
 *   options: Fetch init options (method, body, headers).
 *
 * Returns:
 *   The parsed JSON response body.
 *
 * Raises:
 *   ApiError: When the response is not OK, carrying the server's error message.
 */
async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  const res = await fetch(`${BASE_URL}${path}`, {
    headers: { "Content-Type": "application/json", ...options.headers },
    ...options,
  });
  const body = (await res.json().catch(() => ({}))) as {
    success?: boolean;
    error?: string;
  } & T;
  if (!res.ok) {
    throw new ApiError(body.error ?? `Request failed (${res.status})`, res.status);
  }
  return body;
}

/** Begin login by submitting a mobile number. */
export function login(mobile: string) {
  return request<{ success: true; message: string }>("/api/auth/login", {
    method: "POST",
    body: JSON.stringify({ mobile }),
  });
}

/** Verify the OTP and return a session token. */
export function verifyOtp(mobile: string, otp: string) {
  return request<{ success: true; token: string }>("/api/auth/verify", {
    method: "POST",
    body: JSON.stringify({ mobile, otp }),
  });
}

/** Fetch the movie catalog. */
export function getMovies() {
  return request<{ movies: Movie[] }>("/api/movies");
}

/** Fetch all theatres. */
export function getTheatres() {
  return request<{ theatres: Theatre[] }>("/api/theatres");
}

/** Fetch the theatres showing a given movie. */
export function getMovieTheatres(movieId: number) {
  return request<{ theatres: Theatre[] }>(`/api/movies/${movieId}/theatres`);
}

/** Submit a booking and return its confirmation. */
export function createBooking(payload: BookingPayload) {
  return request<{ success: true; booking: BookingConfirmation }>(
    "/api/bookings",
    { method: "POST", body: JSON.stringify(payload) }
  );
}

"use client";

import {
  createContext,
  useContext,
  useState,
  useCallback,
  ReactNode,
} from "react";
import type { Movie, Theatre, BookingConfirmation } from "@/lib/api";

/** Shape of the in-progress booking held in context. */
export interface BookingDraft {
  movie: Movie | null;
  theatre: Theatre | null;
  seats: string[];
  totalPrice: number;
}

/** Shape of the booking context value. */
interface BookingContextValue {
  /** The authenticated user's mobile number. */
  mobile: string;
  /** The session token issued after OTP verification. */
  token: string;
  /** Whether the user is authenticated. */
  isAuthenticated: boolean;
  /** The in-progress booking selection. */
  draft: BookingDraft;
  /** The confirmed booking after payment. */
  confirmation: BookingConfirmation | null;
  /** Store the authenticated session. */
  setSession: (mobile: string, token: string) => void;
  /** Update the in-progress booking draft. */
  setDraft: (draft: Partial<BookingDraft>) => void;
  /** Store the confirmed booking. */
  setConfirmation: (confirmation: BookingConfirmation) => void;
  /** Clear the session and any in-progress booking. */
  reset: () => void;
}

const BookingContext = createContext<BookingContextValue | undefined>(
  undefined
);

const initialDraft: BookingDraft = {
  movie: null,
  theatre: null,
  seats: [],
  totalPrice: 0,
};

/**
 * Booking provider.
 *
 * Holds the authenticated session and the in-progress booking selection in
 * React Context so each step of the funnel can read and advance the state.
 */
export function BookingProvider({ children }: { children: ReactNode }) {
  const [mobile, setMobile] = useState("");
  const [token, setToken] = useState("");
  const [draft, setDraftState] = useState<BookingDraft>(initialDraft);
  const [confirmation, setConfirmationState] =
    useState<BookingConfirmation | null>(null);

  const setSession = useCallback((nextMobile: string, nextToken: string) => {
    setMobile(nextMobile);
    setToken(nextToken);
  }, []);

  const setDraft = useCallback((partial: Partial<BookingDraft>) => {
    setDraftState((prev) => ({ ...prev, ...partial }));
  }, []);

  const setConfirmation = useCallback((next: BookingConfirmation) => {
    setConfirmationState(next);
  }, []);

  const reset = useCallback(() => {
    setMobile("");
    setToken("");
    setDraftState(initialDraft);
    setConfirmationState(null);
  }, []);

  const value: BookingContextValue = {
    mobile,
    token,
    isAuthenticated: token !== "",
    draft,
    confirmation,
    setSession,
    setDraft,
    setConfirmation,
    reset,
  };

  return (
    <BookingContext.Provider value={value}>{children}</BookingContext.Provider>
  );
}

/**
 * Access the booking context.
 *
 * Raises:
 *   Error: When used outside a BookingProvider.
 */
export function useBooking(): BookingContextValue {
  const ctx = useContext(BookingContext);
  if (ctx === undefined) {
    throw new Error("useBooking must be used within a BookingProvider");
  }
  return ctx;
}

"use client";

import { InputHTMLAttributes, useId } from "react";

export interface FormFieldProps
  extends InputHTMLAttributes<HTMLInputElement> {
  /** The visible label bound to the input. */
  label: string;
  /** Optional validation error message shown below the input. */
  error?: string;
  /** Optional helper text shown when there is no error. */
  hint?: string;
}

/**
 * Labelled form input primitive.
 *
 * Binds the label to the input id, marks required fields, and wires
 * `aria-invalid` / `aria-describedby` to a `role="alert"` error message.
 */
export function FormField({
  label,
  error,
  hint,
  required,
  id,
  ...props
}: FormFieldProps) {
  const autoId = useId();
  const inputId = id ?? autoId;
  const messageId = `${inputId}-message`;

  return (
    <div className="w-full">
      <label
        htmlFor={inputId}
        className="mb-1.5 block text-sm font-medium text-foreground"
      >
        {label}
        {required && <span className="ml-1 text-primary-500">*</span>}
      </label>
      <input
        id={inputId}
        required={required}
        aria-required={required}
        aria-invalid={error ? true : undefined}
        aria-describedby={error || hint ? messageId : undefined}
        className={error ? "border-error focus:ring-error/40" : ""}
        {...props}
      />
      {error ? (
        <p id={messageId} role="alert" className="mt-1.5 text-sm text-error">
          {error}
        </p>
      ) : hint ? (
        <p id={messageId} className="mt-1.5 text-sm text-foreground-muted">
          {hint}
        </p>
      ) : null}
    </div>
  );
}

